# ── PDF Renderer — "Clean Cards" ──────────────────────────────────────────
#
# Canvas-based (not platypus) — needed for precise inline "N)  A + [box] = C"
# layout and for the fixed 5-day-bands-on-one-page week view. WFA brand blue
# header band; boxes/borders carry structure so it survives B&W printing.

_WFA_BLUE = (0x17 / 255, 0x98 / 255, 0xd3 / 255)
_WFA_DARK = (0x0a / 255, 0x01 / 255, 0x01 / 255)
_GREY = (0.55, 0.55, 0.55)


def _split_cloze(question):
    """'3 + ? = 5' -> ('3 + ', ' = 5'); '7×3 =' -> ('7×3 =', '') — the '?'
    (if any) is where the answer box goes; box goes at the end otherwise."""
    if "?" in question:
        left, _, right = question.partition("?")
        return left, right
    return question, ""


def _draw_maths_item(c, x, y_top, row_h, number, question, font_size, box_w, box_h):
    ascender = font_size * 0.72
    baseline = y_top - row_h / 2 - ascender * 0.10
    num_gutter = max(26, font_size * 2)
    c.setFont("Helvetica", font_size)
    c.setFillColorRGB(*_GREY)
    c.drawString(x, baseline, f"{number})")

    left, right = _split_cloze(question)
    if "?" not in question:
        left = left + " ="  # e.g. "10×2" -> "10×2 =" so the box has a "=" before it
    c.setFont(_WORD_FONT, font_size)
    c.setFillColorRGB(*_WFA_DARK)
    lx = x + num_gutter
    c.drawString(lx, baseline, left)
    box_x = lx + c.stringWidth(left, _WORD_FONT, font_size) + 4

    # Anchor the box to the text baseline (not the row's geometric middle)
    # so it visually lines up with "+" and "=" instead of floating relative
    # to them when the row is taller than the text itself.
    box_y = baseline - box_h * 0.22
    c.setFillColorRGB(1, 1, 1)
    c.setStrokeColorRGB(*_WFA_DARK)
    c.setLineWidth(1)
    c.rect(box_x, box_y, box_w, box_h, fill=1, stroke=1)

    if right:
        c.setFont(_WORD_FONT, font_size)
        c.setFillColorRGB(*_WFA_DARK)
        c.drawString(box_x + box_w + 4, baseline, right)


def _draw_recognition_item(c, x, y_top, w, h, text, font_size):
    c.setFillColorRGB(1, 1, 1)
    c.setStrokeColorRGB(0.82, 0.82, 0.82)
    c.setLineWidth(0.6)
    c.rect(x, y_top - h, w, h, fill=1, stroke=1)
    # Per-item safety net: a longer word than the sheet's font size was
    # sized for (e.g. "different" mixed in with short CEW words) shrinks
    # itself rather than overflowing into the next cell.
    pad = w * 0.9
    if c.stringWidth(text, _WORD_FONT, font_size) > pad:
        font_size = max(5, pad / max(c.stringWidth(text, _WORD_FONT, 1.0), 0.01))
    c.setFont(_WORD_FONT, font_size)
    c.setFillColorRGB(*_WFA_DARK)
    ascender = font_size * 0.72
    baseline = y_top - h / 2 - ascender * 0.10
    c.drawCentredString(x + w / 2, baseline, text)


def _draw_dictation_item(c, x, y_top, w, row_h, number, font_size):
    ascender = font_size * 0.72
    baseline = y_top - row_h / 2 - ascender * 0.10
    c.setFont("Helvetica", font_size)
    c.setFillColorRGB(*_GREY)
    c.drawString(x, baseline, f"{number}.")
    line_y = y_top - row_h / 2 - 3
    c.setStrokeColorRGB(0.65, 0.65, 0.65)
    c.setLineWidth(0.8)
    c.line(x + 22, line_y, x + w - 4, line_y)


def _fit_font_for_width(c, texts, font, max_w, min_size=6, max_size=20):
    """Largest font size at which every string in texts fits within max_w —
    takes the longest/widest word as the limiting case so a whole sheet of
    mixed-length words (e.g. CEW: 'to' next to 'different') shares one
    consistent, non-overflowing size."""
    if not texts:
        return max_size
    limiting = min(max_w / max(c.stringWidth(t, font, 1.0), 0.01) for t in texts)
    return max(min_size, min(max_size, limiting))


def _wrap_line(c, text, font, size, max_w):
    words = text.split(" ")
    lines, cur = [], ""
    for w in words:
        trial = f"{cur} {w}".strip()
        if c.stringWidth(trial, font, size) > max_w and cur:
            lines.append(cur)
            cur = w
        else:
            cur = trial
    if cur:
        lines.append(cur)
    return lines


def _pdf_footer_answers(c, margin, usable_w, y_top, questions, subject, display_mode, max_lines=3):
    if subject == "maths":
        label = "Answers: "
        body = ", ".join(
            q["question"].replace("?", q["answer"]) if "?" in q["question"] else f"{q['question']} = {q['answer']}"
            for q in questions
        )
    elif display_mode == "cloze":
        label = "Answers: "
        body = "   ".join(f"{i}) {q['answer']}" for i, q in enumerate(questions, 1))
    elif subject == "spellings" and display_mode == "dictation":
        label = "Words to read aloud: "
        body = ", ".join(q["question"] for q in questions)
    else:
        # Recognition items (phonics, CEW) ARE their own answer — list once.
        label = "Items: "
        body = ", ".join(q["question"] for q in questions)

    lines = _wrap_line(c, label + body, "Helvetica", 6.5, usable_w)
    c.setFont("Helvetica", 6.5)
    c.setFillColorRGB(*_GREY)
    for i, line in enumerate(lines[:max_lines]):
        c.drawString(margin, y_top - i * 8, line)


def _draw_band_content(c, margin, usable_w, grid_top, grid_bottom, sheet, maths_cols=5, recog_cols=8, dict_cols=5):
    """Draw one sheet's items into an arbitrary (grid_top, grid_bottom)
    region — font/box sizes scale with row height, so this works equally
    for a thin week-band or a tall half-page slot. Shared by every sheet
    layout so density stays consistent across single/week/2-per-page."""
    questions = sheet["questions"]
    n = len(questions)
    if n == 0 or grid_top <= grid_bottom:
        return

    if sheet["subject"] == "maths":
        cols = maths_cols
        rows = -(-n // cols)
        gap_x = 4
        col_w = (usable_w - gap_x * (cols - 1)) / cols
        row_h = (grid_top - grid_bottom) / rows
        # Font must be bound by column WIDTH, not just row height — a maths
        # item ("N)  A + [box] = C") needs real horizontal room, and capping
        # only by height let columns overlap when rows were tall but narrow.
        # Measured against the actual text (not an estimate), so it also
        # copes with longer strings (e.g. bonds-to-20's "16 + ? = 20").
        term_texts = []
        for q in questions:
            l, r = _split_cloze(q["question"])
            if "?" not in q["question"]:
                l = l + " ="
            term_texts.append(l + r)
        font_by_width = _fit_font_for_width(c, term_texts, _WORD_FONT, max(col_w - 52, 10))
        font_size = max(6.5, min(14, row_h * 0.40, font_by_width))
        box_h = max(8, min(row_h * 0.62, font_size * 1.15))
        box_w = box_h * 1.5
        for i, q in enumerate(questions):
            row, col = divmod(i, cols)
            x = margin + col * (col_w + gap_x)
            y_top = grid_top - row * row_h
            _draw_maths_item(c, x, y_top, row_h, i + 1, q["question"], font_size, box_w, box_h)

    elif sheet["subject"] == "phonics" or sheet.get("display_mode") == "recognition":
        texts = [q["question"] for q in questions]
        max_len = max((len(t) for t in texts), default=1)
        # Phonics items are single letters/digraphs — the caller's column
        # count is fine. CEW words vary a lot in length ("to" vs
        # "different"), so narrow the columns as the longest word in this
        # set grows, rather than squeezing everything to fit 8 columns.
        cols = recog_cols if sheet["subject"] == "phonics" else max(3, min(recog_cols, 10 - max_len))
        rows = -(-n // cols)
        gap = 3
        col_w = (usable_w - gap * (cols - 1)) / cols
        row_h = min((grid_top - grid_bottom) / rows, col_w * 0.95)     # roughly square cards, never tall strips
        # Each word gets its own size, capped by row height — NOT a single
        # size fit to the sheet's longest word, which made short words
        # ("do", "to") needlessly tiny just because one long outlier
        # ("different") shared the sheet. _draw_recognition_item shrinks
        # only the individual item that actually needs it.
        base_font_size = max(7, min(24, row_h * 0.45))
        for i, q in enumerate(questions):
            row, col = divmod(i, cols)
            x = margin + col * (col_w + gap)
            y_top = grid_top - row * row_h
            _draw_recognition_item(c, x, y_top, col_w, row_h - 1, q["question"], base_font_size)

    else:  # dictation
        cols = dict_cols
        rows = -(-n // cols)
        gap_x = 6
        col_w = (usable_w - gap_x * (cols - 1)) / cols
        row_h = (grid_top - grid_bottom) / rows
        font_size = max(6.5, min(12, row_h * 0.35))
        for i, q in enumerate(questions):
            row, col = divmod(i, cols)
            x = margin + col * (col_w + gap_x)
            y_top = grid_top - row * row_h
            _draw_dictation_item(c, x, y_top, col_w, row_h, i + 1, font_size)


def _compact_header(c, margin, usable_w, y_top, title_bits, right_text, h, name_slot=None):
    """Slim single-line header (name/skill + Time:/Score: fields to fill
    in by hand) instead of a big banner — the point is paper density, not
    branding. A thin blue rule is the only WFA touch."""
    c.setFont("Helvetica-Bold", min(11, h * 0.5))
    c.setFillColorRGB(*_WFA_DARK)
    baseline = y_top - h * 0.62
    c.drawString(margin, baseline, "  |  ".join(title_bits))
    if name_slot is not None:      # title_bits[0] is the child's initials: the browser swaps in the real name
        name_stamps.log(c, margin, baseline, title_bits[0], min(11, h * 0.5), name_slot.get("pupilCode"),
                        post=("  |  " + "  |  ".join(title_bits[1:])) if len(title_bits) > 1 else "", color=_WFA_DARK)
    if right_text:
        c.setFont("Helvetica", min(9, h * 0.42))
        c.setFillColorRGB(*_GREY)
        rw = c.stringWidth(right_text, "Helvetica", min(9, h * 0.42))
        c.drawString(margin + usable_w - rw, baseline, right_text)
    c.setStrokeColorRGB(*_WFA_BLUE)
    c.setLineWidth(1.3)
    c.line(margin, y_top - h, margin + usable_w, y_top - h)
    return y_top - h


# ── Handwriting fonts (joined style uses the school-licensed XCCW fonts, kept in the PRIVATE data repo's fonts/
#    folder, never in this public repo; print style uses Sassoon Infant above) ───────────────────────────────

_HW_FONT_FILES = {"XCCW4a": "XCCW_Joined_4a.ttf", "XCCW4b": "XCCW_Joined_4b.ttf",
                  "XCCWD4a": "XCCW_Joined_Dotted_4a.ttf", "XCCWD4b": "XCCW_Joined_Dotted_4b.ttf",
                  "SassoInfDotB": "SassoInfDotB.ttf", "LinkpenDot": "LinkpenDot.ttf"}
_hw_fonts_ok = None

# Same fonts, sizes and line geometry as the school handwriting tool (app.wallscourt-farm-academy.co.uk/handwriting).
_MM = 72 / 25.4
HW_FONTS = {
    "Cursive, dotted (XCCW)": {"xccw": True, "solid": False, "size": 26, "asc": 8.07 * _MM, "desc": 3.55 * _MM, "xh": 4.8 * _MM},
    "Cursive, solid (XCCW)": {"xccw": True, "solid": True, "size": 26, "asc": 8.07 * _MM, "desc": 3.55 * _MM, "xh": 4.8 * _MM},
    "Print, dotted (Sassoon)": {"font": "SassoInfDotB", "size": 31.8, "asc": 8.0 * _MM, "desc": 3.33 * _MM, "xh": 5.0 * _MM},
    "Pre-cursive, dotted (Linkpen)": {"font": "LinkpenDot", "size": 26, "asc": 9.0434 * _MM, "desc": 4.0 * _MM, "xh": 5.0 * _MM},
}
HW_DEFAULT_FONT = "Cursive, dotted (XCCW)"
_HW_NAVY = (14 / 255, 40 / 255, 65 / 255)
_HW_LBLUE = (0.65, 0.82, 0.93)
_HW_TEAL = (21 / 255, 96 / 255, 130 / 255)


def _hw_joined_fonts_available():
    global _hw_fonts_ok
    if _hw_fonts_ok is not None:
        return _hw_fonts_ok
    from data import REPO_DIR
    folders = [REPO_DIR / "fonts", os.path.join(os.path.dirname(__file__), "fonts"),
               os.path.expanduser("~/projects/wfa-app/fonts")]
    try:
        for name, fn in _HW_FONT_FILES.items():
            path = next((os.path.join(str(f), fn) for f in folders if os.path.exists(os.path.join(str(f), fn))), None)
            if not path:
                raise FileNotFoundError(fn)
            pdfmetrics.registerFont(TTFont(name, path))
        _hw_fonts_ok = True
    except Exception:
        _hw_fonts_ok = False
    return _hw_fonts_ok


def _xccw_runs(text, solid):
    """XCCW join rule: a letter uses the '4b' form when the PREVIOUS letter is o, r, v, w or x (a top exit)."""
    out, prev = [], ""
    for ch in text:
        b = "b" if prev and prev in "orvwx" else "a"
        out.append((ch, ("XCCW4" if solid else "XCCWD4") + b))
        prev = ch.lower()
    return out


def _hw_draw(c, spec, x, y, text):
    c.setFillColorRGB(*_HW_NAVY)
    if spec.get("xccw"):
        for ch, fnt in _xccw_runs(text, spec["solid"]):
            c.setFont(fnt, spec["size"])
            c.drawString(x, y, ch)
            x += c.stringWidth(ch, fnt, spec["size"])
    else:
        c.setFont(spec["font"], spec["size"])
        c.drawString(x, y, text)


def _hw_width(c, spec, text):
    if spec.get("xccw"):
        return sum(c.stringWidth(ch, f, spec["size"]) for ch, f in _xccw_runs(text, spec["solid"]))
    return c.stringWidth(text, spec["font"], spec["size"])


def _is_full_page(sheet):
    """Sheets that get a whole page: phonics, reading-style recognition lists, cloze and handwriting.
    Maths and dictation spelling sit two to a page."""
    if sheet.get("display_mode") == "handwriting":
        return len(sheet["questions"]) > 6          # a few letters or joins fit half a page: two sheets per page
    if sheet.get("display_mode") == "calc":
        return _calc_needs_full_page(sheet["questions"])
    if sheet.get("display_mode") == "fade":
        return len(sheet["questions"]) > 6          # up to six words fit half a page
    if sheet.get("display_mode") == "cloze":
        return True
    if sheet["subject"] == "phonics":
        return len(sheet["questions"]) > 32          # a normal sound sheet (about 25) fits half a page
    return sheet.get("display_mode") == "recognition" and sheet["subject"] != "maths"


def _hw_ruled_row(c, margin, usable_w, baseline, spec, show_x, show_desc, tint=False):
    asc, desc = spec["asc"], spec["desc"]
    c.setDash()
    c.setStrokeColorRGB(*_HW_LBLUE)
    c.setLineWidth(0.5)
    c.line(margin, baseline + asc, margin + usable_w, baseline + asc)
    if show_x:
        c.setStrokeColorRGB(0.80, 0.80, 0.80)
        c.setLineWidth(0.4)
        c.setDash(3, 3)
        c.line(margin, baseline + spec["xh"], margin + usable_w, baseline + spec["xh"])
        c.setDash()
    c.setStrokeColorRGB(*_HW_LBLUE)
    c.setLineWidth(1.4)
    c.line(margin, baseline, margin + usable_w, baseline)
    if show_desc:
        c.setStrokeColorRGB(0.80, 0.80, 0.80)
        c.setLineWidth(0.4)
        c.setDash(8, 4)
        c.line(margin, baseline - desc, margin + usable_w, baseline - desc)
        c.setDash()


def _draw_handwriting_body(c, margin, usable_w, grid_top, grid_bottom, sheet):
    """Ruled rows like the school handwriting tool: the item in dotted writing to trace, then room to keep writing."""
    items = [q["question"] for q in sheet["questions"]]
    if not items:
        return
    name = st.session_state.get("hw_font", HW_DEFAULT_FONT)
    if name not in HW_FONTS or not _hw_joined_fonts_available():
        name, spec = "Print (Sassoon)", {"font": _WORD_FONT, "size": 30, "asc": 8.0 * _MM, "desc": 3.33 * _MM, "xh": 5.0 * _MM}
    else:
        spec = HW_FONTS[name]
    show_x = st.session_state.get("hw_xheight", True)
    show_desc = st.session_state.get("hw_descender", True)
    row_h = spec["asc"] + spec["desc"] + 2.5 * _MM
    c.setFillColorRGB(*_HW_TEAL)
    c.setFont("Helvetica-Bold", 9)
    c.drawString(margin, grid_top - 11, "Trace each item, then continue writing it on the rest of the line.")
    y = grid_top - 18 - spec["asc"]
    # One line per item (the item in dotted writing to trace, then room to keep writing it), then ONE empty line
    # to practise again if the writing was not good enough. Nothing else, so a sheet stays short.
    short = all(len(it) <= 3 for it in items)
    for it in items + [None]:
        if y - spec["desc"] < grid_bottom:
            break
        _hw_ruled_row(c, margin, usable_w, y, spec, show_x, show_desc)
        if it is not None:
            x = margin + 2
            w = _hw_width(c, spec, it)
            _hw_draw(c, spec, x, y, it)
            if short:
                gap = 6 * _mm if len(it) == 1 else 9 * _mm
                x += w + gap
                for _ in range(4):
                    if x + w > margin + usable_w * 0.6:
                        break
                    _hw_draw(c, spec, x, y, it)
                    x += w + gap
        y -= row_h + 2 * _MM
    c.setFillColorRGB(0, 0, 0)


def _draw_upside_down_answers(c, margin, usable_w, y_top, questions):
    """Answer key printed upside down in small grey text (turn the sheet round to check), so it is not easy to copy."""
    text = "Answers:   " + "     ".join(f"{i}) {q['answer']}" for i, q in enumerate(questions, 1))
    lines = _wrap_line(c, text, "Helvetica", 7, usable_w)
    c.saveState()
    c.setFillColorRGB(*_GREY)
    c.setFont("Helvetica", 7)
    c.translate(margin + usable_w, y_top)
    c.rotate(180)
    for i, ln in enumerate(lines[:4]):
        c.drawString(0, -(len(lines[:4]) - 1 - i) * 9, ln)
    c.restoreState()


def _draw_fade_body(c, margin, usable_w, grid_top, grid_bottom, sheet):
    """Look | Trace | Fill the gaps | (fold) | Write it from memory | tick. One row per word."""
    qs = sheet["questions"]
    if not qs:
        return
    dotted = "SassoInfDotB" if _hw_joined_fonts_available() else None
    # Column (start, end) as fractions of the width. The fold line is at 62.5% across on a front side. On the BACK of a
    # double-sided sheet the layout is mirrored (fold at 37.5%), so one crease in the paper works for both sides.
    span = {"look": (0.0, 0.19), "trace": (0.19, 0.40), "gaps": (0.40, 0.62), "write": (0.65, 0.92), "tick": (0.93, 1.0)}
    fold = 0.625
    if sheet.get("mirror"):
        span = {"write": (0.08, 0.35), "tick": (0.0, 0.07), "look": (0.38, 0.57), "trace": (0.57, 0.78), "gaps": (0.78, 1.0)}
        fold = 0.375
    X = {k: margin + v[0] * usable_w for k, v in span.items()}
    X["fold"] = margin + fold * usable_w
    W_END = {k: margin + v[1] * usable_w for k, v in span.items()}
    head_y = grid_top - 5 * _mm
    c.setFont("Helvetica-Bold", 8.5)
    c.setFillColorRGB(*_HW_TEAL)
    for k, lab in (("look", "Look and say"), ("trace", "Trace"), ("gaps", "Fill the gaps"), ("write", "Fold back, then write it")):
        c.drawString(X[k], head_y, lab)
    c.drawString(X["tick"], head_y, "Check")
    c.setFillColorRGB(0, 0, 0)
    top = head_y - 3 * _mm
    row_h = min(15 * _mm, (top - grid_bottom) / len(qs))
    size = min(24, row_h * 0.62)
    # fold line
    c.setDash([3, 3], 0)
    c.setStrokeColorRGB(0.55, 0.55, 0.55)
    c.setLineWidth(0.7)
    c.line(X["fold"], top + 1 * _mm, X["fold"], top - row_h * len(qs))
    c.setDash()
    for i, q in enumerate(qs):
        w = q["question"]
        base = top - (i + 1) * row_h + row_h * 0.28
        c.setStrokeColorRGB(0.85, 0.88, 0.92)
        c.setLineWidth(0.4)
        c.line(margin, top - (i + 1) * row_h, margin + usable_w, top - (i + 1) * row_h)
        # look
        c.setFillColorRGB(0, 0, 0)
        c.setFont(_WORD_FONT, size)
        c.drawString(X["look"] + 1 * _mm, base, w)
        # trace
        if dotted:
            c.setFont(dotted, size * 1.08)
            c.setFillColorRGB(*_HW_NAVY)
        else:
            c.setFillColorRGB(0.7, 0.7, 0.7)
        c.drawString(X["trace"] + 1 * _mm, base, w)
        c.setFillColorRGB(0, 0, 0)
        # fill the gaps
        x = X["gaps"] + 1 * _mm
        c.setFont(_WORD_FONT, size)
        gaps = set(q.get("gaps") or [])
        for j, ch in enumerate(w):
            cw = c.stringWidth(ch, _WORD_FONT, size)
            if j in gaps:
                c.setStrokeColorRGB(0.2, 0.2, 0.2)
                c.setLineWidth(0.9)
                c.line(x, base - 1, x + max(cw, size * 0.42), base - 1)
                x += max(cw, size * 0.42) + 2
            else:
                c.drawString(x, base, ch)
                x += cw + 0.5
        # write from memory
        c.setStrokeColorRGB(0.35, 0.35, 0.35)
        c.setLineWidth(0.8)
        c.line(X["write"] + 1 * _mm, base - 1, W_END["write"] - 2 * _mm, base - 1)
        # check box
        bs = min(6 * _mm, row_h * 0.5)
        c.setLineWidth(0.8)
        c.rect(X["tick"] + 1.5 * _mm, base - 1, bs, bs)


# Square size and rows per grid, largest first; the first that fits is used. Never smaller than 6.5 mm:
# a sheet that does not fit half a page at that size gets a whole page (see _is_full_page).
_CALC_SIZES = ((7 * _mm, 7), (7 * _mm, 6), (6.5 * _mm, 6))


def _calc_needs_full_page(qs):
    usable_w, half_avail, gap, label_h = 180 * _mm, 92 * _mm, 7 * _mm, 8 * _mm
    for sq, rows in _CALC_SIZES:
        n_lines, x = 1, 0
        for q in qs:
            w = _calc_cols(q) * sq
            if x and x + gap + w > usable_w:
                n_lines, x = n_lines + 1, 0
            x += (gap if x else 0) + w
        if n_lines * (label_h + rows * sq) + (n_lines - 1) * 3 * _mm <= half_avail:
            return False
    return True


def _calc_cols(q):
    """Squares across for one question: at least 2 more than the most digits in it (sign column + room to
    exchange); division gets room for the divisor and a remainder."""
    A, B, ans = str(q["a"]), str(q["b"]), str(q["answer"]).split(" r ")[0]
    if q["op"] == "÷":
        return len(A) + 4
    return max(len(A), len(B), len(ans)) + 2


def _draw_calc_body(c, margin, usable_w, grid_top, grid_bottom, sheet):
    """Written calculation: each question on its own squared grid (7 mm squares), set out in columns for the
    written method (column addition, subtraction and multiplication; short division as a bus stop), or with the
    sum written above for the child to set out. Each grid is sized to its question; questions that do not fit
    across go onto the next line."""
    qs = sheet["questions"]
    if not qs:
        return
    gap = 7 * _mm
    label_h = 8 * _mm
    self_layout = sheet.get("calc_layout") == "self"

    def plan(sq, rows):
        lines, line, x = [], [], 0
        for q in qs:
            w = _calc_cols(q) * sq
            if line and x + gap + w > usable_w:
                lines.append(line); line, x = [], 0
            line.append(q); x += (gap if x else 0) + w
        lines.append(line)
        return lines, len(lines) * (label_h + rows * sq) + (len(lines) - 1) * 3 * _mm

    avail = grid_top - grid_bottom
    for sq, rows in _CALC_SIZES:
        lines, need = plan(sq, rows)
        if need <= avail:
            break
    size = sq * 0.72
    y_line = grid_top
    k = 0
    for line in lines:
        bx = margin
        for q in line:
            k += 1
            cols = _calc_cols(q)
            x0 = bx
            top = y_line - label_h
            c.setFont("Helvetica", 10)
            c.setFillColorRGB(*_GREY)
            c.drawString(bx, y_line - 5.5 * _mm, f"{k})")
            if self_layout:                        # the child sets it out: write the sum, leave the squares empty
                sym = {"−": "-"}.get(q["op"], q["op"])
                text = f"{q['a']} {sym} {q['b']} ="
                fs = 15
                while fs > 9 and c.stringWidth(text, _WORD_FONT, fs) > cols * sq - 6 * _mm:
                    fs -= 1
                c.setFillColorRGB(0, 0, 0)
                c.setFont(_WORD_FONT, fs)
                c.drawString(bx + 6 * _mm, y_line - 5.5 * _mm, text)
            # squared paper
            c.setStrokeColorRGB(0.78, 0.84, 0.9)
            c.setLineWidth(0.35)
            for i in range(cols + 1):
                c.line(x0 + i * sq, top, x0 + i * sq, top - rows * sq)
            for j in range(rows + 1):
                c.line(x0, top - j * sq, x0 + cols * sq, top - j * sq)
            bx += cols * sq + gap
            if self_layout:
                continue

            def put(col, row, ch, x0=x0, top=top):
                c.drawCentredString(x0 + (col + 0.5) * sq, top - (row + 1) * sq + sq * 0.24, ch)

            def rule(c0, c1, row_bottom, x0=x0, top=top):
                c.setStrokeColorRGB(0.1, 0.1, 0.1)
                c.setLineWidth(1.1)
                y = top - (row_bottom + 1) * sq
                c.line(x0 + c0 * sq + 1, y, x0 + (c1 + 1) * sq - 1, y)

            A, B = str(q["a"]), str(q["b"])
            c.setFillColorRGB(0, 0, 0)
            c.setFont(_WORD_FONT, size)
            if q["op"] == "÷":
                first = 2                          # divisor in column 1, bus stop from column 2
                for i, ch in enumerate(A):
                    put(first + i, 2, ch)
                put(first - 1, 2, B)
                c.setStrokeColorRGB(0.1, 0.1, 0.1)
                c.setLineWidth(1.1)
                yt = top - 2 * sq
                c.line(x0 + first * sq, yt, x0 + (first + len(A)) * sq, yt)
                c.line(x0 + first * sq, yt, x0 + first * sq, yt - sq)
            else:
                R = cols - 1                       # units column on the right; sign in the first column
                for i, ch in enumerate(reversed(A)):
                    put(R - i, 1, ch)
                for i, ch in enumerate(reversed(B)):
                    put(R - i, 2, ch)
                put(0, 2, {"−": "-"}.get(q["op"], q["op"]))
                ans_row = 4 if q["op"] == "×" else 3   # multiplication: an empty row under the sum for carrying
                rule(0, R, ans_row - 1)            # line above the answer
                rule(0, R, ans_row)                # line below the answer
        y_line -= label_h + rows * sq + 3 * _mm
    c.setFillColorRGB(0, 0, 0)


def _draw_cloze_body(c, margin, usable_w, grid_top, grid_bottom, sheet):
    """Word bank in a box, then numbered sentences with a gap to fill."""
    bank = sheet.get("bank") or []
    groups = sheet.get("bank_groups") or [[w] for w in bank]
    y = grid_top - 3 * _mm
    c.setFont("Helvetica-Bold", 9)
    c.setFillColorRGB(*_GREY)
    c.drawString(margin, y - 3, "Word bank - choose the word that fits each sentence")
    y -= 7 * _mm
    bsz = 17
    if any(len(g) > 1 for g in groups):
        words = "   /   ".join(", ".join(g) for g in groups)      # homophones together, groups separated by a slash
    else:
        words = "     ".join(bank)
    lines = _wrap_line(c, words, _WORD_FONT, bsz, usable_w - 8 * _mm)
    box_h = len(lines) * (bsz + 6) + 8
    c.setStrokeColorRGB(*_WFA_BLUE)
    c.setLineWidth(1.4)
    c.roundRect(margin, y - box_h, usable_w, box_h, 6, stroke=1, fill=0)
    c.setFillColorRGB(0, 0, 0)
    c.setFont(_WORD_FONT, bsz)
    for i, ln in enumerate(lines):
        c.drawString(margin + 4 * _mm, y - 8 - bsz + 2 - i * (bsz + 6), ln)
    y -= box_h + 8 * _mm
    qs = sheet["questions"]
    pitch = max(9 * _mm, min(17 * _mm, (y - grid_bottom) / max(len(qs), 1)))
    gap_w = 34 * _mm
    for i, q in enumerate(qs, 1):
        before, _, after = q["question"].partition("___")
        sz = 16
        label = f"{i})"
        while sz > 9 and 9 * _mm + c.stringWidth(before + after, _WORD_FONT, sz) + gap_w > usable_w:
            sz -= 1
        c.setFont("Helvetica", 11)
        c.setFillColorRGB(*_GREY)
        c.drawString(margin, y - pitch * 0.55, label)
        c.setFillColorRGB(0, 0, 0)
        c.setFont(_WORD_FONT, sz)
        x = margin + 9 * _mm
        c.drawString(x, y - pitch * 0.55, before)
        x += c.stringWidth(before, _WORD_FONT, sz)
        c.setStrokeColorRGB(0.3, 0.3, 0.3)
        c.setLineWidth(0.8)
        c.line(x + 1, y - pitch * 0.58, x + gap_w - 1, y - pitch * 0.58)
        x += gap_w
        c.drawString(x, y - pitch * 0.55, after)
        y -= pitch
    return y



def render_compact_sheet_slot(c, margin, usable_w, slot_top, slot_bottom, pupil, sheet, include_answers):
    """One sheet drawn into a given vertical slot (a whole page, or half a
    page when two are stacked) — the density Innes's old Excel sheets had."""
    bits = [pupil_label(pupil), sheet["skill_name"]]    # initials only: names are added in the teacher's browser
    if sheet.get("day_label"):
        bits.append(sheet["day_label"])
    header_h = min(9 * _mm, (slot_top - slot_bottom) * 0.12)
    mode = sheet.get("display_mode")
    if mode in ("handwriting", "fade"):
        right_text = f"Date: {date.today().strftime('%d/%m/%y')}"
        include_answers = False
    else:
        right_text = f"Time: _______   Score: _______   {date.today().strftime('%d/%m/%y')}"
    header_bottom = _compact_header(c, margin, usable_w, slot_top, bits, right_text, header_h, name_slot=pupil)

    footer_h = (14 * _mm if include_answers else 2 * _mm)
    grid_top = header_bottom - 2
    grid_bottom = slot_bottom + footer_h
    if mode == "cloze":
        end_y = _draw_cloze_body(c, margin, usable_w, grid_top, slot_bottom + (12 * _mm if include_answers else 2 * _mm), sheet)
        if include_answers:
            _draw_upside_down_answers(c, margin, usable_w, end_y - 3 * _mm, sheet["questions"])
        return
    elif mode == "handwriting":
        _draw_handwriting_body(c, margin, usable_w, grid_top, grid_bottom, sheet)
    elif mode == "fade":
        _draw_fade_body(c, margin, usable_w, grid_top, grid_bottom, sheet)
    elif mode == "calc":
        _draw_calc_body(c, margin, usable_w, grid_top, grid_bottom, sheet)
    else:
        _draw_band_content(c, margin, usable_w, grid_top, grid_bottom, sheet, maths_cols=4)

    if include_answers:
        _pdf_footer_answers(c, margin, usable_w, grid_bottom - 10, sheet["questions"], sheet["subject"], sheet.get("display_mode"), max_lines=2)


def render_two_per_page_pdf(c, page_w, page_h, margin, usable_w, slot_entries, include_answers=True):
    """slot_entries: 1 or 2 (pupil, sheet) pairs — stacked top/bottom on
    one page with a dashed cut line between, same as printing 2-up used to
    work in the old Excel sheets. Caller does showPage()."""
    usable_h = page_h - 2 * margin
    cut_gap = 6 * _mm
    half_h = (usable_h - cut_gap) / 2
    top_top = page_h - margin
    top_bottom = top_top - half_h
    bottom_top = top_bottom - cut_gap
    bottom_bottom = bottom_top - half_h

    render_compact_sheet_slot(c, margin, usable_w, top_top, top_bottom, *slot_entries[0], include_answers)

    cut_y = (top_bottom + bottom_top) / 2
    c.setDash([4, 3], 0)
    c.setStrokeColorRGB(0.55, 0.55, 0.55)
    c.setLineWidth(0.8)
    c.line(margin, cut_y, margin + usable_w, cut_y)
    c.setDash()

    if len(slot_entries) > 1:
        render_compact_sheet_slot(c, margin, usable_w, bottom_top, bottom_bottom, *slot_entries[1], include_answers)


# Day colours on the day-per-paper sheets, so a child can find "Wednesday's" sheet in their drawer at a glance.
_DAY_COLOURS = {"Mon": (0x17, 0x98, 0xd3), "Tue": (0x2b, 0xae, 0x62), "Wed": (0xe5, 0x7d, 0x24),
                "Thu": (0x8e, 0x44, 0xad), "Fri": (0xc0, 0x15, 0x7b)}


def _build_day_papers(c, buf, wk_kids, rows, plan_now, ladders_data, wk_answers, wk_cover, review,
                      timetable_page, DAYS, DAY_FULL, page_w, page_h, margin, usable_w, share_paper=True):
    """For double-sided printing, organised by day so children can keep the week in their drawer.

    A piece of paper has four half-page SLOTS (front top, front bottom, back top, back bottom). A half-page sheet
    (maths, handwriting, spelling) takes one slot; a full-page sheet takes a whole side. Each child starts on a new
    piece of paper. A day never starts on a paper it does not fit on, so a day is never split across two papers
    (unless it is bigger than one paper). With share_paper, a short day goes on the same paper as the day before
    when it fits; without it, every day starts a new paper. Every slot and side carries a coloured day heading."""
    pages_done = [0]

    def end_page():
        c.showPage()
        pages_done[0] += 1

    def blank_side():
        c.setFont("Helvetica", 9)
        c.setFillColorRGB(*_GREY)
        c.drawCentredString(page_w / 2, page_h / 2, "This side is blank")
        c.setFillColorRGB(0, 0, 0)
        end_page()

    def band(p, d, top, h, size, note):
        r, g, b = (v / 255 for v in _DAY_COLOURS[d])
        c.setFillColorRGB(r, g, b)
        c.roundRect(margin, top - h, usable_w, h, 6, stroke=0, fill=1)
        c.setFillColorRGB(1, 1, 1)
        c.setFont("Helvetica-Bold", size)
        c.drawString(margin + 5 * _mm, top - h + h * 0.3, DAY_FULL[d])
        c.setFont("Helvetica-Bold", max(10, size * 0.5))
        c.drawRightString(margin + usable_w - 5 * _mm, top - h + h * 0.34,
                          f"{pupil_label(p)}   ·   {note}" if note else pupil_label(p))
        name_stamps.log(c, margin + usable_w - 5 * _mm, top - h + h * 0.34, pupil_label(p), max(10, size * 0.5), p.get("pupilCode"),
                        post=f"   ·   {note}" if note else "", align="r", cover=(r, g, b), color=(1, 1, 1))
        c.setFillColorRGB(0, 0, 0)
        return top - h - 3 * _mm

    n_sheets = 0
    for p in wk_kids:
        plan = plan_now.get(p["id"], {})
        items = [(lab, plan.get(k, [])) for pp, k, lab in rows if pp["id"] == p["id"]]
        if not any(days for _, days in items):
            continue
        if pages_done[0] % 2 == 1:
            blank_side()
        if wk_cover:
            timetable_page(p, items)
            pages_done[0] += 1                 # timetable_page() ends its own page
            blank_side()

        # 1. this child's sheets, day by day
        days = []
        for d in DAYS:
            halves, fulls = [], []
            for pp, k, lab in rows:
                if pp["id"] != p["id"] or not k.startswith("skill:") or d not in plan.get(k, []):
                    continue
                sid = k.split(":", 1)[1]
                step = get_step(ladders_data, sid)
                pool = get_active_window(p, sid, step) if is_windowed(step) else None
                sheet = generate_sheet(p, sid, ladders_data, item_pool=pool, include_review=review, variant=DAYS.index(d))
                if not sheet:
                    continue
                sheet["day_label"] = DAY_FULL[d]
                n_sheets += 1
                (fulls if _is_full_page(sheet) else halves).append(sheet)
            if halves or fulls:
                days.append((d, halves, fulls))

        # 2. place them in slots (slot g: paper g // 4, side g // 2, half g % 2)
        slots = {}

        def place(start, halves, fulls):
            g, out = start, []
            for sh in halves:
                out.append((g, "half", sh)); g += 1
            for sh in fulls:
                if g % 2:
                    g += 1
                out.append((g, "full", sh)); g += 2
            return g, out

        g = 0
        for d, halves, fulls in days:
            if g % 4:                                          # part-way through a piece of paper
                end, out = place(g, halves, fulls)
                fits = share_paper and (end - 1) // 4 == g // 4
                if not fits:
                    g = (g // 4 + 1) * 4
            end, out = place(g, halves, fulls)
            for slot, kind, sh in out:
                slots[slot] = (kind, d, sh)
            g = end
        if not slots:
            continue
        n_pages = (max(slots) // 2) + 1
        n_pages += n_pages % 2                                 # finish the last piece of paper
        day_pages = {}
        for slot, (kind, d, sh) in slots.items():
            day_pages.setdefault(d, set()).add(slot // 2)

        def note_for(d, page):
            pg = sorted(day_pages[d])
            if len(pg) < 2:
                return ""
            i = pg.index(page) + 1
            return f"side {i} of {len(pg)}" + ("  ·  turn over" if i < len(pg) and pg[i] == page + 1 and page % 2 == 0 else "")

        # 3. draw
        for page in range(n_pages):
            top_slot, bottom_slot = slots.get(2 * page), slots.get(2 * page + 1)
            if top_slot is None and bottom_slot is None:
                blank_side()
                continue
            top = page_h - margin
            for entry in (top_slot, bottom_slot):
                if entry:
                    entry[2]["mirror"] = pages_done[0] % 2 == 1      # this side is the back of the paper
            if top_slot and top_slot[0] == "full":
                _, d, sh = top_slot
                y = band(p, d, top, 15 * _mm, 24, note_for(d, page))
                render_compact_sheet_slot(c, margin, usable_w, y, margin, p, sh, wk_answers)
                end_page()
                continue
            gap = 6 * _mm
            half = (top - margin - gap) / 2
            for idx, entry in enumerate((top_slot, bottom_slot)):
                h_top = top if idx == 0 else top - half - gap
                if entry is None:
                    continue
                _, d, sh = entry
                y = band(p, d, h_top, 11 * _mm, 18, note_for(d, page))
                render_compact_sheet_slot(c, margin, usable_w, y, h_top - half, p, sh, wk_answers)
            if top_slot and bottom_slot:
                cut = top - half - gap / 2
                c.setDash([4, 3], 0)
                c.setStrokeColorRGB(0.75, 0.75, 0.75)
                c.setLineWidth(0.6)
                c.line(margin, cut, margin + usable_w, cut)
                c.setDash()
            end_page()
    c.save()
    buf.seek(0)
    return buf.getvalue(), n_sheets


def build_week_pdf(wk_kids, rows, plan_now, ladders_data, wk_answers=True, wk_cover=True, review=False, day_per_paper=False,
                   share_paper=True):
    """One PDF for the chosen children: per child an optional timetable page, then that week's sheets in day order.
    rows: [(pupil, key, label)] where key is "skill:<step id>" (gets a sheet) or anything else (timetable only).
    plan_now: {pupil id: {key: [days]}}. Returns (pdf bytes, number of sheets)."""
    DAYS = ["Mon", "Tue", "Wed", "Thu", "Fri"]
    DAY_FULL = {"Mon": "Monday", "Tue": "Tuesday", "Wed": "Wednesday", "Thu": "Thursday", "Fri": "Friday"}
    from reportlab.lib.pagesizes import A4
    from reportlab.pdfgen import canvas as pdfcanvas
    from io import BytesIO
    buf = BytesIO()
    margin = 15 * _mm
    page_w, page_h = A4
    usable_w = page_w - 2 * margin
    c = pdfcanvas.Canvas(buf, pagesize=A4)

    def _timetable_page(p, items):
        y = page_h - margin - 6 * _mm
        c.setFont("Helvetica-Bold", 20)
        c.setFillColorRGB(0x17 / 255, 0x98 / 255, 0xd3 / 255)
        c.drawString(margin, y, f"{pupil_label(p)} - this week's practice")
        name_stamps.log(c, margin, y, pupil_label(p), 20, p.get("pupilCode"), post=" - this week's practice",
                        color=(0x17 / 255, 0x98 / 255, 0xd3 / 255))
        c.setFillColorRGB(0, 0, 0)
        y -= 14 * _mm
        label_w = usable_w - 5 * 22 * _mm
        row_h = 16 * _mm
        c.setFont("Helvetica-Bold", 12)
        for j, d in enumerate(DAYS):
            c.drawCentredString(margin + label_w + j * 22 * _mm + 11 * _mm, y, DAY_FULL[d][:3])
        y -= 4 * _mm
        for label, days in items:
            c.setStrokeColorRGB(0.6, 0.6, 0.6)
            c.rect(margin, y - row_h, usable_w, row_h)
            c.setFont("Helvetica", 12)
            for ln_i, ln in enumerate(_wrap_line(c, label, "Helvetica", 12, label_w - 4 * _mm)[:2]):
                c.drawString(margin + 2 * _mm, y - 6.5 * _mm - ln_i * 5 * _mm, ln)
            for j, d in enumerate(DAYS):
                cx = margin + label_w + j * 22 * _mm
                c.line(cx, y, cx, y - row_h)
                if d in days:
                    c.setFillColorRGB(0x17 / 255, 0x98 / 255, 0xd3 / 255)
                    c.circle(cx + 11 * _mm, y - row_h / 2, 4.5 * _mm, stroke=0, fill=1)
                    c.setFillColorRGB(0, 0, 0)
            y -= row_h
            if y < margin + row_h:
                break
        c.showPage()

    if day_per_paper:
        return _build_day_papers(c, buf, wk_kids, rows, plan_now, ladders_data, wk_answers, wk_cover, review,
                                 _timetable_page, DAYS, DAY_FULL, page_w, page_h, margin, usable_w, share_paper)

    n_sheets = 0
    for p in wk_kids:
        plan = plan_now.get(p["id"], {})
        items = [(lab, plan.get(k, [])) for pp, k, lab in rows if pp["id"] == p["id"]]
        if not any(days for _, days in items):
            continue
        if wk_cover:
            _timetable_page(p, items)
        pending = []
        def _flush():
            global_pending = list(pending)
            for i2 in range(0, len(global_pending), 2):
                render_two_per_page_pdf(c, page_w, page_h, margin, usable_w, global_pending[i2:i2 + 2], wk_answers)
                c.showPage()
            pending.clear()
        for d in DAYS:
            for pp, k, lab in rows:
                if pp["id"] != p["id"] or not k.startswith("skill:") or d not in plan.get(k, []):
                    continue
                sid = k.split(":", 1)[1]
                step = get_step(ladders_data, sid)
                pool = get_active_window(p, sid, step) if is_windowed(step) else None
                sheet = generate_sheet(p, sid, ladders_data, item_pool=pool, include_review=review, variant=DAYS.index(d))
                if not sheet:
                    continue
                sheet["day_label"] = DAY_FULL[d]
                n_sheets += 1
                if _is_full_page(sheet):
                    _flush()
                    render_compact_sheet_slot(c, margin, usable_w, page_h - margin, margin, p, sheet, wk_answers)
                    c.showPage()
                else:
                    pending.append((p, sheet))
                    if len(pending) == 2:
                        _flush()
        _flush()
    c.save()
    buf.seek(0)
    return buf.getvalue(), n_sheets


_KIND = {"maths": ("maths", None), "recognition": ("phonics", None), "cloze": ("spellings", "cloze"), "fade": ("spellings", "fade"), "calc": ("maths", "calc"),
         "dictation": ("spellings", None), "hw_letters": ("handwriting", "hw_letters"), "hw_joins": ("handwriting", "hw_joins")}


def _targets_to_sheets(load, catalogue, base_ladders):
    """Turn the database's children + targets into the shapes the sheet code already understands."""
    import copy
    areas = {a["id"]: a for a in catalogue["areas"]}
    L = copy.deepcopy(base_ladders)
    pt_steps, bonds_steps = [], []
    kids, rows, plan = [], [], {}
    by_code = {}
    for c in load["children"]:
        p = {"id": c["pupilCode"], "pupilCode": c["pupilCode"], "label": c["label"], "class": c["class"],
             "yearGroup": c.get("yearGroup") or (f"Y{c['class'][0]}" if c.get("class", "")[:1].isdigit() else ""),
             "currentSkills": {}}
        by_code[c["pupilCode"]] = p
    for t in load["targets"]:
        p = by_code.get(t["pupilCode"])
        a = areas.get(t["area"])
        if not p or not a:
            continue
        subject, kind = _KIND.get(a["kind"], ("maths", None))
        sid = f"pt{t['id']}"
        short = a["name"].split(" (")[0]
        name = t["partName"]
        if kind == "calc":
            name = "Written calculation" + ("" if t["part"] == "calc_mix" else f": {t['partName'].lower()}")
        elif kind and kind.startswith("hw"):
            name = f"{short.split(': ')[-1].capitalize()}: {' '.join(t['items'])}"
        elif t["part"].endswith(("_own", "_any")):
            name = f"Sounds: {' '.join(t['items'])}" if a["id"] == "phonics" else f"{short}: {' '.join(t['items'])}"
        step = {"id": sid, "name": name,
                "subject": subject, "items": list(t["items"]),
                "aim": {"correctPerMin": 40, "maxErrors": 2, "timedSec": 60},
                "untimedAim": {"accuracyPct": 100, "minTrials": 3}}
        if kind:
            step["kind"] = kind
        (bonds_steps if a["id"] == "number_bonds" else pt_steps).append(step)
        p["currentSkills"][sid] = {"status": "active", "masteredDate": None, "nextReview": None, "reviewStage": None,
                                   "itemsPerSheet": 25}
        key = f"skill:{sid}"
        rows.append((p, key, f"{short}: {' '.join(t['items'])}"))
        plan.setdefault(p["id"], {})[key] = list(t["days"])
    L["ladders"].append({"id": "pt_targets", "name": "Targets", "subject": "custom", "independent": True, "steps": pt_steps})
    nb = next((l for l in L["ladders"] if l["id"] == "number_bonds"), None)
    if nb is not None:
        nb["steps"] = nb["steps"] + bonds_steps          # keeps the number-bonds sheet layout (a blank on either side)
    for p in by_code.values():
        if p["currentSkills"]:
            kids.append(p)
    kids.sort(key=lambda p: (p["class"], p["label"]))
    return kids, rows, plan, L
